def column_totals(rows):
    if not rows:
        return []
    result = []
    for i in range(len(rows[0])):
        total = 0
        numeric_count = 0
        for r in rows:
            try:
                val = float(r[i])
                total += val
                numeric_count += 1
            except (ValueError, TypeError):
                pass
        if numeric_count > 0:
            if total.is_integer():
                result.append(int(total))
            else:
                result.append(total)
        else:
            result.append("")
    return result

